    if(event.target.closest('[data-guided-chat-retry]')){const id=academy.activeLesson;academy.guidedChat=academy.guidedChat||{};academy.guidedChat[id]={turn:0,score:0,log:[],finished:false};delete academy.conversationDone?.[id];storeAcademy();renderGuidedStep();return}
    if(event.target.closest('[data-guided-conversation-next]')){completeGuided();return}
    const guidedAnswer=event.target.closest('[data-guided-answer]');if(guidedAnswer){document.querySelectorAll('[data-guided-answer]').forEach(b=>b.classList.toggle('selected',b===guidedAnswer));return}
    const guidedRemove=event.target.closest('[data-guided-remove]');if(guidedRemove){const chipIndex=guidedRemove.dataset.guidedRemove;guidedOrder=guidedOrder.filter(item=>String(item.chipIndex)!==String(chipIndex));const source=$(`[data-guided-chip="${CSS.escape(chipIndex)}"]`);if(source){source.disabled=false;source.classList.remove('used')}renderGuidedOrder();return}
    const guidedChip=event.target.closest('[data-guided-chip]');if(guidedChip){guidedOrder.push({word:guidedChip.dataset.word,chipIndex:guidedChip.dataset.guidedChip});guidedChip.disabled=true;guidedChip.classList.add('used');renderGuidedOrder();speak(guidedChip.dataset.word);return}
