    if(event.target.closest('[data-guided-hint]')){const button=event.target.closest('[data-guided-hint]'),cost=chargeGuidedHelp('hint');$('guidedHint').hidden=false;button.disabled=true;button.textContent=`💡 ${msg(`แสดงคำใบ้แล้ว · หัก ${cost} XP`,`ສະແດງຄຳໃບ້ແລ້ວ · ຫັກ ${cost} XP`)}`;guidedFeedback(msg(`ใช้คำใบ้แล้ว หัก ${cost} XP`,`ໃຊ້ຄຳໃບ້ແລ້ວ ຫັກ ${cost} XP`),true);return}
    if(event.target.closest('#guidedCheck')){checkGuidedMeaning();return}
    if(event.target.closest('#guidedOrderCheck')){checkGuidedOrder();return}
    if(event.target.closest('#guidedOrderReset')){guidedOrder=[];renderGuidedStep();return}
    if(event.target.closest('#guidedSpoke')){guidedFeedback(msg('เยี่ยม! การพูดตามช่วยให้จำประโยคได้ดีขึ้น','ດີຫຼາຍ! ການເວົ້າຕາມຊ່ວຍໃຫ້ຈື່ປະໂຫຍກໄດ້ດີຂຶ້ນ'),true);setTimeout(advanceGuided,400);return}
    if(event.target.closest('#guidedReplyCheck')){const answer=$('guidedReply').value.trim();if(answer.length<3){guidedFeedback(msg('ลองพิมพ์คำสั้น ๆ สักนิดนะ หรือเปิดดูตัวอย่างได้','ລອງພິມຄຳສັ້ນໆຈັກໜ້ອຍ ຫຼືເປີດເບິ່ງຕົວຢ່າງໄດ້'))}else{academy.lessonSteps[academy.activeLesson]=3;guidedFeedback(msg('สื่อความหมายได้แล้ว! ดีมาก ลองอ่านประโยคของตัวเองอีกครั้ง','ສື່ຄວາມໝາຍໄດ້ແລ້ວ! ດີຫຼາຍ ລອງອ່ານປະໂຫຍກຂອງເຈົ້າອີກຄັ້ງ'),true);setTimeout(completeGuided,650)}return}
    const difficulty=event.target.closest('[data-difficulty]');if(difficulty){if(difficulty.dataset.difficulty==='support'){const cost=chargeGuidedHelp('support');academy.difficulty='support';storeAcademy();renderGuidedStep();if($('guidedHint')){$('guidedHint').hidden=false;guidedFeedback(msg(`เปิดคำใบ้ช่วยแล้ว · หัก ${cost} XP`,`ເປີດຄຳໃບ້ຊ່ວຍແລ້ວ · ຫັກ ${cost} XP`),true)}return}academy.difficulty='challenge';storeAcademy();return}
    const nextLesson=event.target.closest('[data-next-lesson]');if(nextLesson){startGuidedLesson(nextLesson.dataset.nextLesson);return}
    if(event.target.closest('[data-jump-practice]')){$('academy').scrollIntoView({behavior:'smooth'});closeModule();return}
    const module=event.target.closest('[data-module]');if(module){openModule(module.dataset.module);return}
